<?php declare(strict_types=1);
/** Own scoped CI server and real native/manager sessions, independent of existing development data. */
function ownPressPhotoAttachmentsBrowser(PDO $db,string $key): array
{
    $cfg=\Kulturhus\Native\TestSupport::config();$parent=($cfg['label']??'')==='native-raster-photo-fallback'?sys_get_temp_dir():dirname(getenv('KH_NATIVE_TEST_CONFIG'));$root=rtrim($parent,DIRECTORY_SEPARATOR).'/press-photo-attachments-'.$cfg['database'];
    if(!mkdir($root,0700))throw new RuntimeException('Fresh owned photo browser directory required.');foreach(['media','web','sessions','manager-sessions']as$dir)mkdir($root.'/'.$dir,0700);
    file_put_contents($root.'/private.key',$key);chmod($root.'/private.key',0600);file_put_contents($root.'/auth.key',random_bytes(32));chmod($root.'/auth.key',0600);
    putenv('KH_NATIVE_PRIVATE_KEY_FILE='.$root.'/private.key');putenv('KH_NATIVE_AUTH_KEY_FILE='.$root.'/auth.key');
    \Kulturhus\Native\Shared\Db::run($db,"INSERT INTO clubs VALUES('press-photo-attachments-browser','Own press photo attachments management browser')");
    \Kulturhus\Native\Shared\Db::run($db,"INSERT INTO actors(id,club_id,role,is_superuser) VALUES('press-photo-attachments-browser-admin','press-photo-attachments-browser','member',1)");
    $bridge=new \Kulturhus\Native\Integration\ManagerBridge($db,'press-photo-attachments-browser-admin','native',static fn()=>null);$access=$bridge->access();$club=$access->club();
    \Kulturhus\Native\Shared\Db::run($db,"INSERT IGNORE INTO native_grants VALUES('admin','press','edit')");
    foreach(['press','newsletter']as$module)foreach(['read','edit','manage']as$capability)\Kulturhus\Native\Shared\Db::run($db,'INSERT IGNORE INTO native_grants VALUES(?,?,?)',['admin',$module,$capability]);
    $pixel=imagecreatetruecolor(8,6);imagefill($pixel,0,0,imagecolorallocate($pixel,31,116,99));imagepng($pixel,$root.'/source.png');imagedestroy($pixel);
    $fixtures=[];
    copy(dirname(__DIR__).'/fixtures/photo-import/own-camera.heic',$root.'/own-camera.heic');copy(dirname(__DIR__).'/fixtures/photo-import/own-camera.dng',$root.'/own-camera.dng');
    foreach(['native'=>new \Kulturhus\Native\Shared\Access($db,'admin'),'integrated'=>$access]as$mode=>$actor){
        $mediaDir=$mode==='native'?dirname((string)getenv('KH_NATIVE_TEST_CONFIG')).'/runtime-'.$cfg['database'].'/media':$root.'/media';if(!is_dir($mediaDir))mkdir($mediaDir,0700,true);
        $store=new \Kulturhus\Native\Cms\Media($db,$actor,$mediaDir);$photos=[];foreach(range(0,18)as$i)$photos[]=$store->upload($root.'/source.png','browser-original-'.str_pad((string)$i,3,'0',STR_PAD_LEFT).'.png','Browser photo '.str_pad((string)$i,3,'0',STR_PAD_LEFT))['id'];
        $w=new \Kulturhus\Native\Communication\Workspace($db,$actor,'press',$mediaDir);$original=$w->save(['title'=>'Browser original with file photos','body_html'=>'<p>Actual original human text.</p>','attachment_media_ids'=>array_slice($photos,0,2)]);$w->save(['id'=>$original['id'],'title'=>'Browser later original without photos','body'=>'Actual later human text','attachment_media_ids'=>[]],1);
        $contact=(new \Kulturhus\Native\Communication\PressContacts($db,$actor))->save(['name'=>'Own browser press recipient','email'=>'own-browser-recipient@example.invalid']);$draft=$w->save(['title'=>'Browser human photo release','body_html'=>'<p>Actual human photo text.</p>','recipient_ids'=>[$contact['id']]]);
        $fixtures[$mode]=['current'=>$draft['id'],'original'=>$original['id'],'media'=>$photos[0],'unrelated'=>$photos[3],'photos'=>$photos,'contact'=>$contact['id']];
    }
    $mailKey=\Kulturhus\Verein\Infrastructure\Runtime\ServerKey::nativeRuntime($root.'/private.key');$channels=new \Kulturhus\Verein\MailChannelSettings($db,'press-photo-attachments-browser-admin',$mailKey);$channel=$channels->state();$channel['data']['channels']['press']=array_replace($channel['data']['channels']['press'],['override'=>true,'host'=>'smtp.example.invalid','port'=>'587','user'=>'own-user','password'=>'Own synthetic photo mailbox password','from'=>'club@example.invalid','reply'=>'press@example.invalid']);$channels->save($channel['data'],0);
    $auth=\Kulturhus\Native\Auth\Runtime::service($db);$invite=$auth->createInvitation($access,$bridge->nativeActorId(),'press-photo-attachments-browser@example.invalid');$auth->acceptInvitation($invite['token'],'Own press photo attachments management browser password 2026!');$token=$auth->passwordLogin('press-photo-attachments-browser@example.invalid','Own press photo attachments management browser password 2026!','own-press-photo-attachments-browser')['session_token'];
    \Kulturhus\Native\Shared\Db::run($db,"INSERT INTO actors(id,club_id,role,is_superuser) VALUES('press-photo-attachments-browser-reader','press-photo-attachments-browser','member',0)");
    \Kulturhus\Native\Shared\Db::run($db,"INSERT INTO settings_roles(club_id,id,name,description,members_access,finance_access,settings_access,website_access,version) VALUES('press-photo-attachments-browser','press-photo-attachments-read','Own press photo attachments read role','','none','none',0,?,1)",[json_encode(['press'=>'read','newsletter'=>'read'],JSON_THROW_ON_ERROR)]);
    \Kulturhus\Native\Shared\Db::run($db,"INSERT INTO settings_role_assignments(actor_id,club_id,role_id,version) VALUES('press-photo-attachments-browser-reader','press-photo-attachments-browser','press-photo-attachments-read',1)");
    $readerBridge=new \Kulturhus\Native\Integration\ManagerBridge($db,'press-photo-attachments-browser-reader','native',static fn()=>null);$readerBridge->access();$readerInvite=$auth->createInvitation($access,$readerBridge->nativeActorId(),'press-photo-attachments-read@example.invalid');$auth->acceptInvitation($readerInvite['token'],'Own history read password 2026!');$readerToken=$auth->passwordLogin('press-photo-attachments-read@example.invalid','Own history read password 2026!','own-press-photo-attachments-read')['session_token'];
    foreach(['press','newsletter']as$module)\Kulturhus\Native\Shared\Db::run($db,"INSERT IGNORE INTO native_grants VALUES('reader',?,'read')",[$module]);\Kulturhus\Native\Shared\Db::run($db,"DELETE FROM native_grants WHERE actor_id='reader' AND module='website'");
    $socket=stream_socket_server('tcp://127.0.0.1:0');$port=(int)substr(strrchr(stream_socket_get_name($socket,false),':'),1);fclose($socket);
    $file=$root.'/browser.json';$data=['root'=>$root,'origin'=>'http://127.0.0.1:'.$port,'token'=>$token,'actor'=>'admin','manager_actor'=>'press-photo-attachments-browser-admin','reader_token'=>$readerToken,'reader_actor'=>'reader','reader_manager_actor'=>'press-photo-attachments-browser-reader','photos'=>$fixtures];file_put_contents($file,json_encode($data,JSON_THROW_ON_ERROR));chmod($file,0600);putenv('DVM_PRESS_RECIPIENTS_FIXTURE='.$file);
    $log=fopen($root.'/http.log','wb');$process=proc_open([...\Kulturhus\Native\TestSupport::phpCommand(),...( in_array($cfg['label']??'',['native-large-camera-originals','native-raster-photo-fallback'],true)?['-d',($cfg['label']==='native-raster-photo-fallback'?'memory_limit=64M':'memory_limit=128M'),...array_merge(...array_map(static fn($k,$v)=>['-d',$k.'='.$v],array_keys(parse_ini_string(\Kulturhus\Native\Installer\Deployment::UPLOAD_INI)),array_values(parse_ini_string(\Kulturhus\Native\Installer\Deployment::UPLOAD_INI))))]:[]),'-S','127.0.0.1:'.$port,'-t',$root.'/web',dirname(__DIR__).'/support/press-recipients-router.php'],[0=>['pipe','r'],1=>$log,2=>$log],$pipes);if(!is_resource($process))throw new RuntimeException('Own history server unavailable.');fclose($pipes[0]);
    for($i=0;$i<100;$i++){$probe=@stream_socket_client('tcp://127.0.0.1:'.$port,$errno,$error,.1);if($probe){fclose($probe);break;}usleep(50000);}
    return ['process'=>$process,'log'=>$log,'root'=>$root,'input'=>$data];
}
